<section class="space-y-6">
    <header>
        <p class="text-sm font-semibold uppercase tracking-widest text-primary">System activity</p>
        <h1 class="mt-2 text-3xl font-bold">Audit Logs</h1>
        <p class="mt-2 text-zinc-600 dark:text-zinc-300">Review changes across the system, including who made them and when.</p>
    </header>

    <form id="audit-search-form" method="get" action="/audit-logs" class="grid gap-4 rounded-xl bg-white p-4 shadow-sm ring-1 ring-zinc-200 sm:grid-cols-2 xl:grid-cols-6 dark:bg-dark-card dark:ring-zinc-800">
        <div class="sm:col-span-2"><label for="audit-search" class="mb-2 block text-sm font-medium">Search activity</label><input id="audit-search" name="q" type="search" value="<?= e($query) ?>" placeholder="Order code, action, or record ID" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"></div>
        <div><label for="audit-range" class="mb-2 block text-sm font-medium">Date range</label><select id="audit-range" name="range" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"><option value="">All dates</option><option value="today" <?= $range === 'today' ? 'selected' : '' ?>>Today</option><option value="yesterday" <?= $range === 'yesterday' ? 'selected' : '' ?>>Yesterday</option><option value="last7" <?= $range === 'last7' ? 'selected' : '' ?>>Last 7 days</option><option value="custom" <?= $range === 'custom' ? 'selected' : '' ?>>Custom range</option></select></div>
        <div><label for="audit-module" class="mb-2 block text-sm font-medium">Module</label><select id="audit-module" name="module" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"><option value="">All modules</option><?php foreach ($modules as $key => $label): ?><option value="<?= e($key) ?>" <?= $module === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
        <div><label for="audit-user" class="mb-2 block text-sm font-medium">Staff member</label><select id="audit-user" name="user" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"><option value="">All staff</option><?php foreach ($staff as $person): ?><option value="<?= (int) $person['id'] ?>" <?= (string) $userId === (string) $person['id'] ? 'selected' : '' ?>><?= e($person['username']) ?><?= $person['role'] === 'admin' ? ' (Admin)' : '' ?></option><?php endforeach; ?></select></div>
        <div><label for="audit-action" class="mb-2 block text-sm font-medium">Action</label><select id="audit-action" name="action" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"><option value="">All actions</option><?php foreach ($actions as $key => $label): ?><option value="<?= e($key) ?>" <?= $action === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
        <div data-audit-custom-range class="<?= $range === 'custom' ? '' : 'hidden' ?>"><label for="audit-from" class="mb-2 block text-sm font-medium">From</label><input id="audit-from" name="from" type="date" value="<?= e($fromDate) ?>" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"></div>
        <div data-audit-custom-range class="<?= $range === 'custom' ? '' : 'hidden' ?>"><label for="audit-to" class="mb-2 block text-sm font-medium">To</label><input id="audit-to" name="to" type="date" value="<?= e($toDate) ?>" class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"></div>
    </form>
    <p id="audit-status" class="sr-only" role="status" aria-live="polite"></p>

    <article class="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-zinc-200 dark:bg-dark-card dark:ring-zinc-800">
        <div class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm">
            <thead class="bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500 dark:bg-zinc-900 dark:text-zinc-400"><tr><th class="px-5 py-3">Date &amp; time</th><th class="px-5 py-3">Staff member</th><th class="px-5 py-3">Activity</th><th class="px-5 py-3">Record</th><th class="px-5 py-3">Details</th></tr></thead>
            <tbody id="audit-log-rows" class="divide-y divide-zinc-100 dark:divide-zinc-800">
                <?php foreach ($logs as $log): ?>
                    <?php $detailData = is_string($log['details']) ? json_decode($log['details'], true) : null; $linkedOrderId = $log['entity_type'] === 'order' ? (int) $log['entity_id'] : (int) ($detailData['order_id'] ?? 0); ?>
                    <tr class="align-top">
                        <td class="whitespace-nowrap px-5 py-4 text-zinc-600 dark:text-zinc-300"><?= e(date('d M Y, H:i:s', strtotime((string) $log['created_at']))) ?></td>
                        <td class="px-5 py-4"><?= e($log['username'] ?? 'Deleted user') ?></td>
                        <td class="px-5 py-4"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= e(\App\Controllers\AuditLogController::actionClass((string) $log['action'])) ?>"><?= e($actions[$log['action']] ?? ucwords(str_replace(['.', '_'], ' ', (string) $log['action']))) ?></span></td>
                        <td class="px-5 py-4"><?php if ($linkedOrderId > 0): ?><a href="/orders/<?= $linkedOrderId ?>" class="font-medium text-primary hover:underline"><?= e(in_array($log['entity_type'], ['payment', 'refund'], true) ? 'Order #' . $linkedOrderId . ' · ' . ucfirst((string) $log['entity_type']) . ' #' . (int) $log['entity_id'] : ucfirst((string) $log['entity_type']) . ' #' . (int) $log['entity_id']) ?></a><?php else: ?><?= e(ucfirst((string) $log['entity_type'])) ?><?= $log['entity_id'] ? ' #' . (int) $log['entity_id'] : '' ?><?php endif; ?></td>
                        <td class="max-w-xl px-5 py-4"><p class="font-medium"><?= e($log['summary']) ?></p><button id="audit-toggle-<?= (int) $log['id'] ?>" type="button" class="mt-2 inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary" data-audit-toggle aria-expanded="false" aria-controls="audit-details-<?= (int) $log['id'] ?>" data-audit-id="<?= (int) $log['id'] ?>" data-audit-actor="<?= e($log['username'] ?? 'Deleted user') ?>" data-audit-time="<?= e(date('d M Y, H:i:s', strtotime((string) $log['created_at']))) ?>" data-audit-module="<?= e(ucfirst((string) $log['entity_type'])) ?>" data-audit-action="<?= e($actions[$log['action']] ?? ucwords(str_replace(['.', '_'], ' ', (string) $log['action']))) ?>" data-audit-record="<?= e(ucfirst((string) $log['entity_type']) . ($log['entity_id'] ? ' #' . (int) $log['entity_id'] : '')) ?>" data-audit-data="<?= e(json_encode(is_array($detailData) ? $detailData : [], JSON_INVALID_UTF8_SUBSTITUTE | JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?: '{}') ?>">View Change Details</button></td>
                    </tr>
                    <tr id="audit-details-<?= (int) $log['id'] ?>" hidden><td colspan="5" class="px-4 pb-4"><div data-audit-panel class="rounded-xl border border-violet-200 bg-violet-50/70 p-4 text-zinc-900 dark:border-violet-900 dark:bg-zinc-950 dark:text-zinc-100"></div></td></tr>
                <?php endforeach; ?>
                <?php if ($logs === []): ?><tr><td colspan="5" class="px-5 py-12 text-center text-zinc-500 dark:text-zinc-400">No audit activity found.</td></tr><?php endif; ?>
            </tbody>
        </table></div>
        <?php $first = $total === 0 ? 0 : (($page - 1) * $perPage + 1); $last = min($page * $perPage, $total); ?>
        <div class="flex flex-wrap items-center justify-between gap-3 border-t border-zinc-100 px-5 py-3 dark:border-zinc-800"><p id="audit-result-count" class="text-xs text-zinc-500 dark:text-zinc-400">Showing <?= $first ?>–<?= $last ?> of <?= $total ?> events</p><nav id="audit-pagination" aria-label="Audit log pages" class="flex items-center gap-2"><?php if ($page > 1): $previous = $_GET; $previous['page'] = $page - 1; ?><a href="/audit-logs?<?= e(http_build_query($previous)) ?>" data-audit-page="<?= $page - 1 ?>" class="rounded-md px-3 py-1.5 text-sm text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800">Previous</a><?php endif; ?><span data-audit-page-label class="px-2 text-xs text-zinc-500 dark:text-zinc-400">Page <?= $page ?> of <?= $totalPages ?></span><?php if ($page < $totalPages): $next = $_GET; $next['page'] = $page + 1; ?><a href="/audit-logs?<?= e(http_build_query($next)) ?>" data-audit-page="<?= $page + 1 ?>" class="rounded-md px-3 py-1.5 text-sm text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800">Next</a><?php endif; ?></nav></div>
    </article>
</section>
